SELECT s.id AS id, s.user_id AS userId, s.student_no AS studentNo, u.real_name AS realName, u.avatar AS avatar, u.gender AS gender, d1.name AS major, d2.name AS clazz, s.entry_year AS entryYear, tg.create_time AS createTime FROM ts_guidance tg JOIN students s ON tg.student_user_id = s.user_id LEFT JOIN user u ON s.user_id = u.id LEFT JOIN sys_dept d1 ON s.major_id = d1.id LEFT JOIN sys_dept d2 ON s.class_id = d2.id
tg.teacher_user_id = #{teacherId}
AND s.student_no LIKE concat('%', #{dto.studentNo}, '%')
AND s.major_id = #{dto.majorId}
AND s.class_id = #{dto.classId}
AND s.entry_year = #{dto.entryYear}
ORDER BY s.entry_year DESC, s.student_no ASC

